extends SceneTree
const Model=preload("res://scripts/card_system/production_model.gd")
var template=Model.new()
var failures:=0
var records:Array=[]
func _initialize():call_deferred("run")
func make_game(a:Dictionary,b:Dictionary,seed_value:int):
 var m=Model.new(template)
 if not m.start_alpha(a.cards,b.cards,seed_value,2):failures+=1;printerr("FAIL invalid deck ",a.id,"/",b.id);return null
 var exchange:Array=[]
 for i in m.state.hero.hand.size():
  if m.catalog.card(m.state.hero.hand[i]).cost>3:exchange.append(i)
 m.mulligan(exchange)
 return m
func finish(m):
 m.choose_origin(2)
 if m.state.stage=="second":
  var highest:=-1
  for i in m.state.hero.hand.size():
   if m.catalog.card(m.state.hero.hand[i]).cost>3:highest=i
  if highest>=0:m.second_exchange(highest)
  m.second_change((int(m.state.origins.hero)+1)%5);m.finish_opening()
 var calls:=0
 while m.state.winner==null and m.state.error.is_empty() and calls<500:
  m.ai_turn("hero");calls+=1
 return calls
func paired_seeds(before:Dictionary,after:Dictionary,op:Dictionary,reverse:bool)->Array:
 var result:Array=[];var counts={"hero":0,"enemy":0}
 for seed in 4096:
  var a=make_game(op,before,seed) if reverse else make_game(before,op,seed)
  var b=make_game(op,after,seed) if reverse else make_game(after,op,seed)
  if a==null or b==null:return []
  if a.state.coin==b.state.coin and counts[a.state.coin]<2:result.append(seed);counts[a.state.coin]+=1
  if counts.hero==2 and counts.enemy==2:return result
 failures+=1;printerr("FAIL paired counterbalanced seeds ",before.id,op.id);return []
func play(condition:String,deck:Dictionary,op:Dictionary,seed:int,reverse:bool):
 var m=make_game(op,deck,seed) if reverse else make_game(deck,op,seed)
 var calls=finish(m)
 var side="enemy" if reverse else "hero"
 var result={"condition":condition,"deck":deck.id,"opponent":op.id,"seed":seed,"reverse":reverse,"first":m.state.coin,"winner":m.state.winner,"won":m.state.winner==side,"round":m.state.round,"censored":m.state.winner==null,"error":m.state.error,"calls":calls,"state_sha256":JSON.stringify(m.snapshot(),"",true).sha256_text(),"event_sha256":JSON.stringify(m.events,"",true).sha256_text()}
 if result.censored or not result.error.is_empty():failures+=1;printerr("FAIL experiment ",JSON.stringify(result))
 records.append(result)
func run():
 var source:Dictionary=JSON.parse_string(FileAccess.get_file_as_string("res://data/production/test_decks.json"))
 var baseline:Dictionary={}
 for d in source.decks:baseline[d.id]=d
 var candidate:Dictionary=JSON.parse_string(FileAccess.get_file_as_string("res://work/production/balance-candidates.json"))
 var source_hashes:Dictionary={}
 for path in ["data/production/cards.json","data/production/test_decks.json","scripts/production/ai_policy.gd","scripts/card_system/production_model.gd"]:source_hashes[path]=FileAccess.get_sha256("res://"+path)
 for after in candidate.decks:
  var before:Dictionary=baseline[after.id]
  for opponent in ["prod-time","prod-aggro","prod-control"]:
   for reverse in [false,true]:
    var seeds=paired_seeds(before,after,baseline[opponent],reverse)
    for seed in seeds:
     play("baseline",before,baseline[opponent],seed,reverse)
     play("candidate",after,baseline[opponent],seed,reverse)
    print("PAIRED EXPERIMENT ",after.id," vs ",opponent," reverse=",reverse," records=",records.size())
 var summary:Dictionary={}
 for r in records:
  var key:String=r.deck+"/"+r.condition
  if not summary.has(key):summary[key]={"games":0,"wins":0,"round_sum":0,"censored":0,"errors":0}
  var s:Dictionary=summary[key];s.games+=1;s.round_sum+=int(r.round)
  if r.won:s.wins+=1
  if r.censored:s.censored+=1
  if not r.error.is_empty():s.errors+=1
 if records.size()!=240:failures+=1;printerr("FAIL incomplete real experiment matrix ",records.size(),"/240")
 var source_changes:Array=[]
 for path in source_hashes:
  if source_hashes[path]!=FileAccess.get_sha256("res://"+path):source_changes.append(path)
 if not source_changes.is_empty():failures+=1;printerr("FAIL sources changed ",source_changes)
 var report={"expected_games":240,"source_changes":source_changes,"scope":"Actual same-seed and same-first-seat paired deck-composition experiments; model/card/AI unchanged; three strong opponents and both roles; not full metagame balance","failures":failures,"games":records,"summary":summary,"source_sha256":source_hashes,"candidate_sha256":FileAccess.get_sha256("res://work/production/balance-candidates.json")}
 var f=FileAccess.open("res://work/production/paired-deck-results.json",FileAccess.WRITE);f.store_string(JSON.stringify(report,"\t",true));f.close()
 print("PAIRED EXPERIMENT RESULT ",JSON.stringify(summary)," failures=",failures)
 quit(0 if failures==0 else 1)
